<?php require 'config/database.php'; $rows=$pdo->query("SELECT * FROM documents ORDER BY id DESC")->fetchAll(); ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dokumen</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="container"><a href="index.php">← Beranda</a><h1>Dokumen & Download</h1><div class="grid"><?php foreach($rows as $r):?><div class="card"><h3><?=htmlspecialchars($r['title'])?></h3><p><?=htmlspecialchars($r['description'])?></p><a class="btn" href="<?=htmlspecialchars($r['file_url'])?>" target="_blank">Buka Dokumen</a></div><?php endforeach;?></div></div></body></html>